<body>
  <header>
    <h1>Contact Us</h1>
    <p class="subtitle">We'd love to hear from you. Send us a message and we'll respond as soon as possible.</p>
  </header>

  <main id="maincontent" tabindex="-1">
    <div class="status-message" id="statusMessage" role="status" aria-live="polite">
      <span class="status-icon" id="statusIcon"></span>
      <span id="statusText"></span>
    </div>

    <form id="contactForm" novalidate>
      <div class="form-field">
        <label for="fullName">
          Full name
          <span class="required-marker" aria-hidden="true">*</span>
        </label>
        <input
          id="fullName"
          name="fullName"
          type="text"
          required
          autocomplete="name"
          aria-describedby="fullName-error"
        >
        <p id="fullName-error" class="error-text"></p>
      </div>

      <div class="form-field">
        <label for="email">
          Email address
          <span class="required-marker" aria-hidden="true">*</span>
        </label>
        <input
          id="email"
          name="email"
          type="email"
          required
          autocomplete="email"
          aria-describedby="email-help email-error"
        >
        <p id="email-help" class="help-text">We'll only use this to reply to your message.</p>
        <p id="email-error" class="error-text"></p>
      </div>

      <div class="form-field">
        <label for="phone">Phone number</label>
        <input
          id="phone"
          name="phone"
          type="tel"
          autocomplete="tel"
          aria-describedby="phone-help"
        >
        <p id="phone-help" class="help-text">Format: (123) 456-7890 or +1 123 456 7890</p>
      </div>

      <button type="submit">Send Message</button>
    </form>
  </main>

  <script>
    const form = document.getElementById('contactForm');
    const statusMessage = document.getElementById('statusMessage');
    const statusIcon = document.getElementById('statusIcon');
    const statusText = document.getElementById('statusText');
    const mainContent = document.getElementById('maincontent');

    form.addEventListener('submit', handleSubmit);

    function clearFieldErrors() {
      const errorElements = document.querySelectorAll('.error-text');
      errorElements.forEach(el => {
        el.textContent = '';
        el.classList.remove('show');
      });

      const inputs = form.querySelectorAll('input');
      inputs.forEach(input => {
        input.removeAttribute('aria-invalid');
      });
    }

    function validateForm() {
      clearFieldErrors();
      let isValid = true;
      const errors = {};

      const fullNameInput = document.getElementById('fullName');
      const fullNameValue = fullNameInput.value.trim();
      if (!fullNameValue) {
        errors.fullName = 'Error: Please enter your full name.';
        isValid = false;
      }

      const emailInput = document.getElementById('email');
      const emailValue = emailInput.value.trim();
      if (!emailValue) {
        errors.email = 'Error: Please enter your email address.';
        isValid = false;
      } else if (!isValidEmail(emailValue)) {
        errors.email = 'Error: Please enter a valid email address (e.g., name@example.com).';
        isValid = false;
      }

      if (errors.fullName) {
        const errorEl = document.getElementById('fullName-error');
        errorEl.textContent = errors.fullName;
        errorEl.classList.add('show');
        fullNameInput.setAttribute('aria-invalid', 'true');
      }

      if (errors.email) {
        const errorEl = document.getElementById('email-error');
        errorEl.textContent = errors.email;
        errorEl.classList.add('show');
        emailInput.setAttribute('aria-invalid', 'true');
      }

      return isValid;
    }

    function isValidEmail(email) {
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      return emailRegex.test(email);
    }

    function showStatus(type, message) {
      if (type === 'success') {
        statusIcon.textContent = '✓';
        statusMessage.classList.remove('error');
        statusMessage.classList.add('success');
      } else {
        statusIcon.textContent = '✕';
        statusMessage.classList.remove('success');
        statusMessage.classList.add('error');
      }
      statusText.textContent = message;
    }

    function handleSubmit(e) {
      e.preventDefault();

      if (!validateForm()) {
        const firstInvalidInput = form.querySelector('input[aria-invalid="true"]');
        if (firstInvalidInput) {
          firstInvalidInput.focus();
        }
        showStatus('error', 'Please fix the errors above and try again.');
        return;
      }

      const formData = new FormData(form);
      const data = {
        fullName: formData.get('fullName'),
        email: formData.get('email'),
        phone: formData.get('phone') || null,
      };

      console.log('Form submitted:', data);

      showStatus('success', 'Thank you for your message! We'll be in touch soon.');

      form.reset();
      mainContent.focus();

      setTimeout(() => {
        statusMessage.classList.remove('success', 'error');
      }, 5000);
    }
  </script>
</body>
</html>
