+      </div>
+
+      <div class="form-field">
+        <label for="phone">Phone number</label>
+        <input
+          id="phone"
+          name="phone"
+          type="tel"
+          autocomplete="tel"
+          aria-describedby="phone-help"
+        >
+        <p id="phone-help" class="help-text">Format: (123) 456-7890 or +1 123 456 7890</p>
+      </div>
+
+      <button type="submit">Send Message</button>
+    </form>
+  </main>
+
+  <script>
+    const form = document.getElementById('contactForm');
+    const statusMessage = document.getElementById('statusMessage');
+    const statusIcon = document.getElementById('statusIcon');
+    const statusText = document.getElementById('statusText');
+    const mainContent = document.getElementById('maincontent');
+
+    form.addEventListener('submit', handleSubmit);
+
+    function clearFieldErrors() {
+      const errorElements = document.querySelectorAll('.error-text');
+      errorElements.forEach(el => {
+        el.textContent = '';
+        el.classList.remove('show');
+      });
+
+      const inputs = form.querySelectorAll('input');
+      inputs.forEach(input => {
+        input.removeAttribute('aria-invalid');
+      });
+    }
+
+    function validateForm() {
+      clearFieldErrors();
+      let isValid = true;
+      const errors = {};
+
+      const fullNameInput = document.getElementById('fullName');
+      const fullNameValue = fullNameInput.value.trim();
+      if (!fullNameValue) {
+        errors.fullName = 'Error: Please enter your full name.';
+        isValid = false;
+      }
+
+      const emailInput = document.getElementById('email');
+      const emailValue = emailInput.value.trim();
+      if (!emailValue) {
+        errors.email = 'Error: Please enter your email address.';
+        isValid = false;
+      } else if (!isValidEmail(emailValue)) {
+        errors.email = 'Error: Please enter a valid email address (e.g., name@example.com).';
+        isValid = false;
+      }
+
+      if (errors.fullName) {
+        const errorEl = document.getElementById('fullName-error');
+        errorEl.textContent = errors.fullName;
+        errorEl.classList.add('show');
+        fullNameInput.setAttribute('aria-invalid', 'true');
+      }
+
